insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('f2a11031-7dc9-51b5-813f-894f2004803c'::uuid, 'Technology', 'analysis', 'A school app suddenly becomes slow for many students. What would you do first?', '[{"id": "o1", "text": "Look for a measurable bottleneck and isolate it", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o2", "text": "Check which part affects the most users and prioritize it", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o3", "text": "Ask students what feels frustrating and redesign the experience", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o4", "text": "Compare the main symptoms before choosing a direction", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('46394b4c-a48d-521f-89ce-3bd1cb9ce2b2'::uuid, 'Technology', 'decision', 'You are given a messy set of student timetable data. What sounds most satisfying?', '[{"id": "o1", "text": "Find patterns and inconsistencies in the data", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o2", "text": "Choose rules that make scheduling efficient", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o3", "text": "Think about how students should see the timetable", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o4", "text": "Break the problem into smaller manageable parts", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('638d4489-e68a-5766-9991-15ce4ad220e7'::uuid, 'Technology', 'people_creative', 'A website feature is confusing students. How would you investigate?', '[{"id": "o1", "text": "Inspect where the interaction breaks down", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o2", "text": "Compare the feature''s impact with other priorities", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o3", "text": "Observe what students expect the interface to do", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o4", "text": "Gather a few perspectives before deciding", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('8cde178c-23a8-587b-bf3a-cd8074c5d85a'::uuid, 'Technology', 'balanced', 'You need to explain a complex technical idea to a younger student. What approach feels natural?', '[{"id": "o1", "text": "Use a logical sequence of examples", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o2", "text": "Connect it to a practical outcome", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o3", "text": "Use a simple visual or analogy", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o4", "text": "Ask what they already understand and build from there", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('f60f40e9-c39a-5ce8-a37d-5165c5d943aa'::uuid, 'Technology', 'analysis', 'Two solutions can fix the same technical problem. How do you choose?', '[{"id": "o1", "text": "Compare evidence, reliability and trade-offs", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o2", "text": "Choose the option with the best value for the effort", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o3", "text": "Consider which solution will feel clearer to users", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o4", "text": "List the pros and cons before committing", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('30213df4-316c-5744-ba1b-025440fa7a11'::uuid, 'Technology', 'decision', 'A dataset contains several unusual values. What catches your attention first?', '[{"id": "o1", "text": "Whether the values follow a meaningful pattern", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o2", "text": "Whether they could affect an important decision", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o3", "text": "Whether they represent a real user or real-world case", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o4", "text": "Whether more context is needed before interpreting them", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('8a342b39-a951-56fd-bb1e-dec98219b2ba'::uuid, 'Technology', 'people_creative', 'A digital product has a feature that few people use. What would you investigate?', '[{"id": "o1", "text": "Usage patterns and possible technical friction", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o2", "text": "Whether the feature creates enough value to keep", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o3", "text": "Whether people understand the feature", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o4", "text": "Different explanations for the low usage", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('53d6f2d5-c29c-5401-be91-6ace74c73334'::uuid, 'Technology', 'balanced', 'You have one afternoon to improve an online form. What sounds most interesting?', '[{"id": "o1", "text": "Reduce logical errors and unnecessary steps", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o2", "text": "Prioritize the changes with the biggest practical impact", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o3", "text": "Make the form easier and more intuitive to use", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o4", "text": "Test several small improvements and compare them", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('817cdf04-4ab9-59da-81b2-4ca418c6a4df'::uuid, 'Technology', 'analysis', 'When a technical project fails, what response feels most useful?', '[{"id": "o1", "text": "Trace the cause systematically", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o2", "text": "Decide what should be fixed first", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o3", "text": "Talk through the experience of the people affected", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o4", "text": "Review assumptions and try again", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
