insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('e9ab80ef-c87c-5125-a068-f86b73c5476d'::uuid, 'Law', 'people_creative', 'You are given a set of documents about a dispute. Where do you start?', '[{"id": "o1", "text": "Organize the facts and sources", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o2", "text": "Identify the issues that could change the outcome", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o3", "text": "Consider the people and context behind the documents", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o4", "text": "Build a timeline and compare the accounts", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('21a7dce9-0272-5dc5-964b-d908166e4dd8'::uuid, 'Law', 'balanced', 'A friend wants to make a strong argument. What would you suggest?', '[{"id": "o1", "text": "Define the reasoning clearly", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o2", "text": "Focus on the strongest point for the intended outcome", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o3", "text": "Explain the argument in a way others can understand", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o4", "text": "Consider the counterargument too", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('bd0f3eff-0214-5020-a0ab-88e3ec2ae7f9'::uuid, 'Law', 'analysis', 'Someone makes a claim without evidence. How do you react?', '[{"id": "o1", "text": "Ask what evidence supports it", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o2", "text": "Consider whether the claim affects an important decision", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o3", "text": "Ask how the claim impacts the people involved", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o4", "text": "Look for independent information", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('7a9f80e3-dbaa-5043-b83f-2e33b2a6aaf1'::uuid, 'Law', 'decision', 'Two interpretations of a rule are possible. What do you examine?', '[{"id": "o1", "text": "The exact language and logic", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o2", "text": "Which interpretation better serves the rule''s purpose", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o3", "text": "The practical effect on people", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o4", "text": "How similar situations were treated", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('a1781cae-140c-5ad2-82fe-bd181c823a7f'::uuid, 'Law', 'people_creative', 'A team has limited time to prepare an argument. What comes first?', '[{"id": "o1", "text": "Organize the strongest evidence", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o2", "text": "Prioritize the issue that could decide the case", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o3", "text": "Understand the audience and affected people", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o4", "text": "Create a clear argument structure", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('a962f696-9358-5278-9f23-6c5ac8d4cfbc'::uuid, 'Law', 'balanced', 'A witness remembers an event differently months later. What do you do?', '[{"id": "o1", "text": "Compare details with other evidence", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o2", "text": "Assess which differences matter to the case", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o3", "text": "Understand how memory and context could affect the account", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o4", "text": "Avoid a conclusion until more evidence is checked", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('e65d36b6-73b4-5df4-9242-63f7af3daa1a'::uuid, 'Law', 'analysis', 'A legal research task feels rewarding when...', '[{"id": "o1", "text": "The facts and rules fit together logically", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o2", "text": "You find the point that changes the outcome", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o3", "text": "You help clarify a difficult situation for people", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o4", "text": "You discover and compare competing interpretations", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('d6d5955d-41af-5d57-b8fe-f876f930600c'::uuid, 'Law', 'decision', 'You discover evidence that weakens your preferred argument. What is your instinct?', '[{"id": "o1", "text": "Reassess the logic", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o2", "text": "Decide how it changes the strength of the case", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o3", "text": "Consider the interests of everyone affected", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o4", "text": "Include it and revise the argument fairly", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('d1b77bd6-b683-538e-ac26-3581e2847163'::uuid, 'Law', 'people_creative', 'A community must choose between two policies. How would you help?', '[{"id": "o1", "text": "Compare the facts and assumptions", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o2", "text": "Evaluate trade-offs and likely outcomes", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o3", "text": "Consider different groups'' experiences", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o4", "text": "Compare evidence for both options", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('cbd02b6c-9954-5227-8bd1-5eb805af013b'::uuid, 'Law', 'balanced', 'A long document contains important details. What feels natural?', '[{"id": "o1", "text": "Structure the information and identify key facts", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o2", "text": "Find the points that could change the decision", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o3", "text": "Notice the human context and consequences", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o4", "text": "Cross-check details across sections", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('e54199a1-e341-5d8d-9309-b078aae9cc38'::uuid, 'Law', 'analysis', 'A good argument to you is one that...', '[{"id": "o1", "text": "Is logically supported", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o2", "text": "Targets the most important issue", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o3", "text": "Can be understood and considered by people", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o4", "text": "Anticipates reasonable counterarguments", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
