insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('6328a208-6e68-5d6f-9247-02f13e9fcf4c'::uuid, 'Law', 'people_creative', 'What would keep you engaged in a law-related task?', '[{"id": "o1", "text": "Analyzing facts and rules", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o2", "text": "Solving a difficult dispute", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o3", "text": "Understanding people and social systems", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o4", "text": "Building and testing arguments", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('5caa2572-2218-53ee-a879-a885553c3887'::uuid, 'Healthcare', 'analysis', 'A fictional patient has several symptoms. What would you do first?', '[{"id": "o1", "text": "Organize the symptoms and evidence", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}, {"id": "o2", "text": "Prioritize the issue that could be most important", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o3", "text": "Consider the person''s overall situation", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o4", "text": "Gather more information before concluding", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
