insert into public.assessment_questions (id, interest, dimension, question, options, active) values ('91776df3-e16e-5423-bc35-86dc49cac936'::uuid, 'Healthcare', 'decision', 'A case contains incomplete information. What is your instinct?', '[{"id": "o1", "text": "Identify the most useful missing evidence", "scores": {"science": 0.8, "commerce": 6.0, "arts": 0.6}}, {"id": "o2", "text": "Prioritize what could change the decision", "scores": {"science": 0.4, "commerce": 0.8, "arts": 6.0}}, {"id": "o3", "text": "Ask about the person''s context and concerns", "scores": {"science": 2.2, "commerce": 2.2, "arts": 2.2}}, {"id": "o4", "text": "Gather multiple relevant sources", "scores": {"science": 6.0, "commerce": 0.8, "arts": 0.4}}]'::jsonb, true) on conflict (id) do update set interest=excluded.interest, dimension=excluded.dimension, question=excluded.question, options=excluded.options, active=excluded.active;
