create extension if not exists pgcrypto;

create table if not exists public.students (
  id uuid primary key default gen_random_uuid(),
  clerk_user_id text not null unique,
  profile jsonb not null default '{}'::jsonb,
  recommendations jsonb not null default '[]'::jsonb,
  roadmap jsonb not null default '[]'::jsonb,
  progress jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists students_clerk_user_id_idx on public.students (clerk_user_id);
create or replace function public.touch_students_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;
drop trigger if exists students_touch_updated_at on public.students;
create trigger students_touch_updated_at
before update on public.students
for each row execute function public.touch_students_updated_at();
-- The FastAPI backend uses the Supabase service-role key and therefore bypasses RLS.
-- Do not expose that key in the frontend.


create table if not exists public.assessment_questions (
  id uuid primary key,
  interest text not null,
  dimension text not null,
  question text not null,
  options jsonb not null,
  active boolean not null default true,
  created_at timestamptz not null default now()
);

create index if not exists assessment_questions_interest_idx on public.assessment_questions (interest, active);

create table if not exists public.assessment_attempts (
  id uuid primary key default gen_random_uuid(),
  clerk_user_id text not null unique,
  question_ids jsonb not null default '[]'::jsonb,
  answers jsonb not null default '[]'::jsonb,
  status text not null,
  alignment_score integer not null default 0,
  answer_stream_scores jsonb not null default '{}'::jsonb,
  interest_stream_scores jsonb not null default '{}'::jsonb,
  stream_suggestions jsonb not null default '[]'::jsonb,
  answered_questions integer not null default 0,
  total_questions integer not null default 15,
  completed_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists assessment_attempts_clerk_user_id_idx on public.assessment_attempts (clerk_user_id);

create or replace function public.touch_assessment_attempt_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end;
$$;

drop trigger if exists assessment_attempts_touch_updated_at on public.assessment_attempts;
create trigger assessment_attempts_touch_updated_at before update on public.assessment_attempts for each row execute function public.touch_assessment_attempt_updated_at();

